use super::*;
fn mission()->Value{let n=64*64;json!({"map":{"width":64,"height":64,"tileSize":32,"world":0,"original":true,"seed":4300,"revision":0,"tiles":vec![0;n],"territory":vec![0;n],"terrainCodes":vec![0;n],"originalTiles":vec![0;n],"bridgeBase":vec![-1;n],"bridgeHp":[],"nativeRoadGraph":{"regions":[]},"nativeTerrainPlane":vec![0;16384]},"sectors":[],"buildings":[],"spawns":[{"type":"medium","team":0,"x":320,"y":320,"squad":1},{"type":"gatling","team":1,"x":1800,"y":1800,"squad":2}],"crates":[],"originalObjects":[],"walls":[],"nativeWorldBuildings":(0..35).map(|slot|json!({"nativeSlot":slot,"kind":-1,"x":-1,"y":-1,"hp":-1,"maxHp":-1,"flags6":0,"buildingId":null})).collect::<Vec<_>>()})}
fn driving()->Game{let mut g=Game::new(0,1,4300);g.apply_original(&mission()).unwrap();g.ai_teams.clear();let id=g.units[0].id;g.command(&json!({"kind":"move","ids":[id],"team":0,"x":1400,"y":320}));for _ in 0..10{g.winner=None;g.step(0.059);}assert_eq!(g.native_route_boundary,None);assert!(g.owns_native_route(0));assert!(g.units[0].native_remaining48>0);assert!(g.units[0].original_motion.is_some());g}
fn stop(g:&mut Game){let id=g.units[0].id;g.command(&json!({"kind":"stop","ids":[id],"team":0}));}
#[test]fn accepted4_preserves_actual_line_heads_and_hardware_before_callback(){let mut g=driving();let slot=g.units[0].native_slot.unwrap();let line=g.units[0].original_motion.as_ref().unwrap().source_line_fields();let remaining=g.units[0].native_remaining48;let links=g.native_routes.borrow().pool.links[slot];let w=g.units[0].native_hardware_slot.unwrap();let hardware=g.native_hardware_pool[w].clone();let rng=g.original_rng.words;stop(&mut g);assert_eq!(g.units[0].native_order5c,4);assert_eq!(g.units[0].original_motion.as_ref().map(|l|l.source_line_fields()),Some(line),"accepted4 must not destroy only the line while raw48 and heads remain");assert_eq!(g.units[0].native_remaining48,remaining);assert_eq!(g.native_routes.borrow().pool.links[slot],links);assert_eq!(g.native_hardware_pool[w].attributes,hardware.attributes);assert_eq!(g.native_hardware_pool[w].order,hardware.order);assert_eq!(g.original_rng.words,rng);assert_eq!(g.units[0].order,"guard");assert!(g.units[0].target.is_none());assert!(g.units[0].hold_position&&g.units[0].explicit_stop);}
#[test]fn accepted4_callback_runs_native_stop_then_common_without_missing_line(){let mut g=driving();stop(&mut g);let before=(g.units[0].x,g.units[0].y);g.step(0.059);assert_eq!(g.native_route_boundary,None);assert_eq!(g.units[0].native_order5c,0);let w=g.units[0].native_hardware_slot.unwrap();assert_eq!(g.native_hardware_pool[w].order.selected_target12,255);assert!(g.units[0].native_remaining48>0);assert!(g.units[0].original_motion.is_some());for _ in 0..10{g.step(0.059);assert_eq!(g.native_route_boundary,None);}assert_ne!((g.units[0].x,g.units[0].y),before,"source patterned motion may continue after opcode4; no immediate-halt promise");}
#[test]fn accepted4_keeps_real_dodge_until_its_own_callback(){let mut g=driving();let p=[(g.units[0].x/2.)as i16,(g.units[0].y/2.)as i16];g.react_native_dodge(None,1,p,[p[0]+8,p[1]+8]);assert!(g.units[0].native_dodge.is_some());let counter=g.units[0].native_dodge.as_ref().unwrap().counter8c;let remaining=g.units[0].native_remaining48;stop(&mut g);assert_eq!(g.units[0].native_dodge.as_ref().map(|d|d.counter8c),Some(counter));assert_eq!(g.units[0].native_flags64&64,64);assert_eq!(g.units[0].native_remaining48,remaining);}
#[test]fn accepted4_does_not_reuse_stale_opcode_for_disabled_or_unmanaged_fallback(){for mode in 0..3{let mut g=driving();let id=g.units[0].id;g.units[0].native_order5c=4;if mode==1{g.map.native_road_graph=None;}if mode==2{let slot=g.units[0].native_slot.unwrap();g.native_routes.get_mut().managed[slot]=false;}g.command(&json!({"kind":"stop","ids":[id],"team":0,"nativeEvent":mode!=0}));assert!(g.units[0].original_motion.is_none(),"fallback{mode} must remain outside native accepted4");}}
unsafe fn abi_req(v:Value)->Value{let b=serde_json::to_vec(&v).unwrap();let n=run(b.as_ptr(),b.len());serde_json::from_slice(std::slice::from_raw_parts(output(),n)).unwrap()}
#[test]fn accepted4_real_json_abi_retains_line_through_the_next_callback(){unsafe{let mut r=abi_req(json!({"op":"init","mission":0,"difficulty":1,"seed":4300,"aiTeams":[],"originalMission":mission()}));assert!(r["error"].is_null(),"{r}");let id=r["units"][0]["id"].clone();abi_req(json!({"op":"command","kind":"move","ids":[id],"team":0,"x":1400,"y":320}));for _ in 0..10{r=abi_req(json!({"op":"tick","dt":0.059}));}assert!(r["nativeRouteBoundary"].is_null(),"{r}");abi_req(json!({"op":"command","kind":"stop","ids":[id],"team":0}));r=abi_req(json!({"op":"tick","dt":0.059}));assert!(r["nativeRouteBoundary"].is_null(),"accepted4 ABI boundary: {}",r["nativeRouteBoundary"]);assert_eq!(r["units"][0]["nativeOrder5c"],0);}}
